**JavaScript скрипт (script.js):**

```javascript
document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('reviewForm');
    const reviewsContainer = document.getElementById('reviewsContainer');

    form.addEventListener('submit', function(event) {
        event.preventDefault(); // Предотвращаем стандартное поведение формы

        const userReview = document.getElementById('reviewText').value;

        // Создание нового отзыва
        const reviewItem = document.createElement('div');
        reviewItem.classList.add('review');
        reviewItem.innerHTML = `
            <strong>Пользователь:</strong> ${userReview}<br>
            <strong>Время: </strong>${new Date().toLocaleTimeString()}<br>
        `;

        // Добавление отзыва в контейнер
        reviewsContainer.appendChild(reviewItem);

        // Очистка поля ввода
        document.getElementById('reviewText').value = '';
    });
});
```

